          "ਜੱਲ੍ਹਿਆਂਵਾਲਾ ਬਾਗ਼ ਦੇ ਸਾਕੇ (13 ਅਪਰੈਲ, 1919) ਤੋਂ ਬਾਅਦ ਸਕੂਲ ਵਿੱਚ ਅੰਗਰੇਜ਼ ਅਫ਼ਸਰ ਨੂੰ ਸਲਾਮੀ ਦੇਣ ਦਾ ਹੁਕਮ ਆਇਆ। ਸੁਖਦੇਵ ਨੇ ਸਲਾਮੀ ਦੇਣ ਤੋਂ ਸਾਫ਼ ਇਨਕਾਰ ਕਰ ਦਿੱਤਾ।",
