          "ਦੂਜੀ ਟੀਮ ਤੇ ਹੱਲਾ ਬੋਲਣ ਵਾਲਾ ਖਿਡਾਰੀ ਧਾਵੀ ਕਹਾਉਂਦਾ ਹੈ ਅਤੇ ਉਸ ਨੂੰ ਰੋਕਣ ਵਾਲੇ ਜਾਫੀ ਕਹਾਉਂਦੇ ਹਨ।",
          "ਧਾਵੀ ਇੱਕੋ ਸਾਹ ਵਿੱਚ “ਕਬੱਡੀ-ਕਬੱਡੀ” ਬੋਲਦਾ ਰਹਿੰਦਾ ਹੈ। ਜੇ ਸਾਹ ਟੁੱਟ ਜਾਵੇ ਤਾਂ ਵਿਰੋਧੀ ਟੀਮ ਨੂੰ ਅੰਕ ਮਿਲਦਾ ਹੈ।",
          "ਅੰਤ ਵਿੱਚ ਵੱਧ ਅੰਕ ਲੈਣ ਵਾਲੀ ਟੀਮ ਜੇਤੂ ਹੁੰਦੀ ਹੈ।"
