        { q: "“ਆਓ” ਅਤੇ “ਜਾਓ” ਕਹਿਣ ਵਿੱਚ ਕੀ ਫ਼ਰਕ ਹੈ?", a: "“ਜਾਓ” ਕਹਿਣ ਵਾਲਾ ਆਪ ਕੰਮ ਨਹੀਂ ਕਰਦਾ, ਜਦਕਿ “ਆਓ” ਕਹਿਣ ਵਾਲਾ ਆਪ ਵੀ ਨਾਲ ਕੰਮ ਕਰਦਾ ਹੈ।" }
