          "ਗੁਰੂ ਗੋਬਿੰਦ ਸਿੰਘ ਜੀ ਦਾ ਜਨਮ ਪਟਨਾ ਸਾਹਿਬ ਵਿੱਚ ਹੋਇਆ ਅਤੇ ਮਾਤਾ ਜੀ ਨੇ ਉਨ੍ਹਾਂ ਦਾ ਪਾਲਣ-ਪੋਸ਼ਣ ਕੀਤਾ।"
