          "ਅੱਧੀ ਛੁੱਟੀ ਵਿੱਚ ਦੋਸਤਾਂ ਨਾਲ ਮਿਲ ਕੇ ਖਾਣਾ ਖਾਓ, ਜੂਠਾ ਨਾ ਛੱਡੋ ਅਤੇ ਖਾਣ ਤੋਂ ਪਹਿਲਾਂ ਹੱਥ ਧੋਵੋ।",
